(() => {
  "use strict";

  const { seed, parseAmount, format, cleanName, key, mergeIngredients, assess, consume, stock } = window.Pantry;
  const $ = selector => document.querySelector(selector);
  const storageKey = "pantry-table-v1";
  const servingsInput = $("#servings");
  const pantryDialog = $("#pantry-dialog");
  const recipeDialog = $("#recipe-dialog");
  const mealDialog = $("#meal-dialog");

  const iconPaths = {
    bowl: '<path d="M3 12h18a8 8 0 0 1-7 8H10a8 8 0 0 1-7-8Z"/><path d="M9 22h6M9 8c-2-2 2-3 0-5m6 5c-2-2 2-3 0-5"/>',
    pantry: '<path d="M6 7V4h12v3M5 7h14v2l-1 2v8a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2v-8L5 9V7Zm1 7h12m-12 3h12"/>',
    rice: '<path d="M3 13h18a8 8 0 0 1-8 7h-2a8 8 0 0 1-8-7Zm2 0 1-3 3-1 2-3 3 2 3 1 2 4m-9-2h.01m4-1h.01"/>',
    lentils: '<circle cx="8" cy="8" r="3"/><circle cx="16.5" cy="10.5" r="3"/><circle cx="10" cy="17" r="3"/>',
    carrots: '<path d="M15 9c-2-2-5-1-6 1L4 20l10-5c3-1 3-4 1-6Zm1 0 4-4m-4 4V4m0 5h5M9 12l2 2m-4 2 1 1"/>',
    eggs: '<path d="M18 14c0 4-2.5 6-6 6s-6-2-6-6S8.5 4 12 4s6 6 6 10Z"/>',
    onions: '<path d="M12 3v5m-3-4 3 4 3-4m-3 4c-3.3 3-7 4.6-7 8a7 5 0 0 0 14 0c0-3.4-3.7-5-7-8Zm0 0c-1.5 3.5-3 5.4-3 8 0 2 1 4 3 5 2-1 3-3 3-5 0-2.6-1.5-4.5-3-8Z"/>',
    plus: '<path d="M12 5v14M5 12h14"/>',
    minus: '<path d="M5 12h14"/>',
    edit: '<path d="m14 6 4 4m-13 9 4-1L20 7l-4-4L5 14l-1 6 5-2"/>',
    arrow: '<path d="M4 12h15m-6-6 6 6-6 6"/>',
    check: '<path d="m5 12 4 4L19 6"/>',
    info: '<circle cx="12" cy="12" r="9"/><path d="M12 11v5m0-8h.01"/>',
    close: '<path d="m6 6 12 12M18 6 6 18"/>',
    alert: '<path d="M12 8v5m0 3h.01"/><circle cx="12" cy="12" r="9"/>'
  };

  function icon(name) {
    return '<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">' + iconPaths[name] + "</svg>";
  }

  function escape(value) {
    return String(value).replace(/[&<>"']/g, character => ({
      "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
    })[character]);
  }

  function plural(count, singular) {
    return count + " " + singular + (count === 1 ? "" : "s");
  }

  let persistent = true;
  let state = seed();
  let servings = 2;
  let pendingMeal = null;
  let editingIngredient = null;
  let toastTimer;

  function storageUnavailable() {
    persistent = false;
    const notice = $("#storage-notice");
    notice.textContent = "Browser storage is unavailable. Changes will last until you close or reload this page.";
    notice.hidden = false;
  }

  function latestState() {
    if (persistent) {
      try {
        const saved = localStorage.getItem(storageKey);
        if (saved) return JSON.parse(saved);
      } catch {
        storageUnavailable();
      }
    }
    return state;
  }

  function commit(transform) {
    const apply = () => {
      state = latestState();
      const next = transform(state);
      if (!next) {
        render();
        return false;
      }
      if (persistent) {
        try {
          localStorage.setItem(storageKey, JSON.stringify(next));
        } catch {
          storageUnavailable();
        }
      }
      state = next;
      render();
      return true;
    };

    if (persistent && navigator.locks) {
      let started = false;
      return navigator.locks.request(storageKey, () => {
        started = true;
        return apply();
      }).catch(error => {
        if (started) throw error;
        return apply();
      });
    }
    return Promise.resolve(apply());
  }

  function announce(message) {
    const toast = $("#message");
    clearTimeout(toastTimer);
    toast.textContent = message;
    toast.classList.add("visible");
    toastTimer = setTimeout(() => toast.classList.remove("visible"), 4800);
  }

  function render() {
    const pantry = state.pantry;
    const stocked = pantry.filter(item => item.amount !== "0").length;
    $("#pantry-count").textContent = plural(stocked, "ingredient") + " in stock";
    $("#pantry-list").innerHTML = pantry.map((item, index) => {
      const name = escape(item.name);
      const kind = item.name.toLowerCase();
      const ingredientIcon = ["rice", "lentils", "carrots", "eggs", "onions"].includes(kind) ? kind : "pantry";
      return '<li><button class="pantry-row" type="button" data-edit="' + index + '" aria-label="Edit ' + name + ', ' + format(item.amount, item.unit) + '">' +
        '<span class="ingredient-icon ' + ingredientIcon + '">' + icon(ingredientIcon) + '</span>' +
        '<span class="ingredient-name">' + name + '</span><span class="quantity">' + format(item.amount, item.unit) + '</span>' +
        '<span class="edit-mark">' + icon("edit") + "</span></button></li>";
    }).join("");
    const ingredientNames = new Set(pantry.map(item => item.name));
    $("#ingredient-names").innerHTML = [...ingredientNames].map(name => '<option value="' + escape(name) + '"></option>').join("");

    const recipes = state.recipes.map(recipe => ({
      recipe,
      requirements: assess(recipe, pantry, servings)
    }));
    const ready = recipes.filter(({ requirements }) => requirements.every(item => !item.shortage)).length;
    $("#recipe-summary").textContent = ready + " of " + recipes.length + " ready for " + plural(servings, "serving");
    $("#recipe-list").innerHTML = recipes.map(({ recipe, requirements }) => recipeCard(recipe, requirements)).join("");
  }

  function recipeCard(recipe, requirements) {
    const missing = requirements.filter(item => item.shortage);
    const ready = missing.length === 0;
    const title = escape(recipe.name);
    const cover = recipe.image
      ? '<img src="' + escape(recipe.image) + '" width="800" height="800" alt="">'
      : '<div class="cover-placeholder">' + icon("bowl") + "</div>";
    const rows = requirements.map(item => {
      const shortage = item.shortage
        ? '<small>Short ' + format(item.shortage, item.unit) + '</small>'
        : "";
      return '<li class="' + (item.shortage ? "short" : "") + '"><span class="ingredient-name">' + escape(item.name) + '</span><span>' +
        format(item.amount, item.unit) + shortage + "</span></li>";
    }).join("");
    return '<article class="recipe-card panel" aria-labelledby="recipe-' + recipe.id + '">' +
      '<div class="recipe-cover">' + cover +
      '<span class="badge ' + (ready ? "ready" : "missing") + '">' + icon(ready ? "check" : "alert") +
      (ready ? "Ready to cook" : missing.length + " short") + "</span></div>" +
      '<div class="recipe-body"><h3 id="recipe-' + recipe.id + '">' + title + "</h3>" +
      '<ul class="requirements" aria-label="Scaled ingredients">' + rows + "</ul>" +
      '<button class="button ' + (ready ? "primary" : "unavailable") + ' cook" type="button" data-cook="' + recipe.id +
      '" aria-label="' + (ready ? "Cook " : "Missing ingredients for ") + title + '"' + (ready ? "" : " disabled") + ">" +
      (ready ? "Cook this meal" + icon("arrow") : "Missing ingredients") + "</button></div></article>";
  }

  function setServings(value) {
    servings = Math.max(1, Math.min(999, value));
    servingsInput.value = servings;
    $("#fewer").disabled = servings === 1;
    $("#more").disabled = servings === 999;
    render();
  }

  function setError(form, message = "") {
    const error = form.querySelector(".form-error");
    error.hidden = !message;
    error.textContent = message;
  }

  function getIngredient(nameInput, amountInput, unitInput, allowZero = false) {
    const name = cleanName(nameInput.value);
    const unit = unitInput.value;
    const amount = parseAmount(amountInput.value, unit, allowZero);
    if (!name) {
      nameInput.focus();
      throw new Error("Enter an ingredient name.");
    }
    if (amount === null) {
      amountInput.focus();
      const range = allowZero ? "zero or more" : "greater than zero";
      throw new Error(unit === "item" ? "Enter a whole number of items, " + range + "." :
        "Enter grams as a number or fraction, " + range + ".");
    }
    return { name, unit, amount };
  }

  function openPantry(item) {
    const form = $("#pantry-form");
    form.reset();
    setError(form);
    editingIngredient = item;
    $("#pantry-dialog-title").textContent = item ? "Edit ingredient" : "Add to your pantry";
    $("#pantry-hint").textContent = item ? "Set the amount you have on hand." :
      "Adding an existing ingredient increases its stock in the selected unit.";
    form.elements.ingredient.value = item?.name || "";
    form.elements.ingredient.readOnly = Boolean(item);
    form.elements.unit.value = item?.unit || "item";
    form.elements.unit.disabled = Boolean(item);
    form.elements.amount.value = item?.amount || "";
    form.querySelector('[type="submit"]').textContent = item ? "Save amount" : "Add to pantry";
    pantryDialog.showModal();
    if (item) form.elements.amount.select();
  }

  const ingredientRow = '<label class="field">Ingredient<input name="ingredient" list="ingredient-names" required maxlength="80" placeholder="e.g. Rice"></label>' +
    '<label class="field">Amount<input name="amount" inputmode="decimal" required maxlength="48" placeholder="0"></label>' +
    '<label class="field">Unit<select name="unit"><option value="item">Items</option><option value="g">Grams</option></select></label>' +
    '<button class="icon-button remove-line" type="button" aria-label="Remove ingredient row">' + icon("close") + "</button>";

  function updateLineControls() {
    const buttons = $("#recipe-ingredients").querySelectorAll(".remove-line");
    buttons.forEach(button => { button.disabled = buttons.length < 2; });
  }

  function addLine(focus) {
    const row = document.createElement("div");
    row.className = "ingredient-form-row";
    row.innerHTML = ingredientRow;
    $("#recipe-ingredients").append(row);
    updateLineControls();
    if (focus) row.querySelector("input").focus();
  }

  function openRecipe() {
    $("#recipe-form").reset();
    setError($("#recipe-form"));
    $("#recipe-ingredients").textContent = "";
    addLine(false);
    recipeDialog.showModal();
  }

  function openMeal(id) {
    const recipe = state.recipes.find(item => item.id === id);
    if (!recipe || assess(recipe, state.pantry, servings).some(item => item.shortage)) return;
    pendingMeal = { id, servings };
    $("#meal-title").textContent = recipe.name;
    $("#meal-description").textContent = "Confirm " + plural(servings, "serving") + " to deduct these ingredients from your pantry.";
    $("#meal-ingredients").innerHTML = assess(recipe, state.pantry, servings).map(item =>
      "<li><span>" + escape(item.name) + "</span><strong>" + format(item.amount, item.unit) + "</strong></li>").join("");
    setError($("#meal-form"));
    mealDialog.showModal();
  }

  function onSubmit(form, submit) {
    const button = form.querySelector('[type="submit"]');
    form.addEventListener("submit", async event => {
      event.preventDefault();
      if (button.disabled) return;
      setError(form);
      button.disabled = true;
      try {
        await submit(form);
      } catch (error) {
        setError(form, error.message);
      } finally {
        button.disabled = false;
      }
    });
  }

  document.querySelectorAll("[data-icon]").forEach(element => { element.innerHTML = icon(element.dataset.icon); });
  document.querySelectorAll("[data-close]").forEach(button => {
    button.addEventListener("click", () => button.closest("dialog").close());
  });

  servingsInput.addEventListener("input", () => {
    if (!/^[0-9]{1,3}$/.test(servingsInput.value) || Number(servingsInput.value) === 0) return;
    setServings(Number(servingsInput.value));
  });
  servingsInput.addEventListener("blur", () => { servingsInput.value = servings; });
  servingsInput.addEventListener("keydown", event => {
    if (event.key === "Enter") servingsInput.blur();
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      setServings(servings + (event.key === "ArrowDown" ? -1 : 1));
    }
  });
  $("#fewer").addEventListener("click", () => setServings(servings - 1));
  $("#more").addEventListener("click", () => setServings(servings + 1));

  $("#add-pantry").addEventListener("click", () => openPantry(null));
  $("#pantry-list").addEventListener("click", event => {
    const button = event.target.closest("[data-edit]");
    if (button) openPantry(state.pantry[Number(button.dataset.edit)]);
  });

  $("#add-recipe").addEventListener("click", openRecipe);
  $("#add-line").addEventListener("click", () => addLine(true));
  $("#recipe-ingredients").addEventListener("click", event => {
    const remove = event.target.closest(".remove-line");
    if (remove) {
      const row = remove.closest(".ingredient-form-row");
      const next = row.nextElementSibling || row.previousElementSibling;
      row.remove();
      updateLineControls();
      next.querySelector("input").focus();
    }
  });
  $("#recipe-ingredients").addEventListener("change", event => {
    if (event.target.name !== "ingredient") return;
    const name = cleanName(event.target.value).toLowerCase();
    const units = state.pantry.filter(item => item.name.toLowerCase() === name);
    if (units.length === 1) event.target.closest(".ingredient-form-row").querySelector("select").value = units[0].unit;
  });

  $("#recipe-list").addEventListener("click", event => {
    const button = event.target.closest("[data-cook]");
    if (button) openMeal(Number(button.dataset.cook));
  });

  onSubmit($("#pantry-form"), async form => {
    const editing = Boolean(editingIngredient);
    const ingredient = getIngredient(form.elements.ingredient, form.elements.amount, form.elements.unit, editing);
    await commit(current => ({ ...current, pantry: stock(current.pantry, ingredient, editing) }));
    pantryDialog.close();
    const position = state.pantry.findIndex(item => key(item) === key(ingredient));
    if (editing) $(".pantry-row[data-edit='" + position + "']").focus();
    announce(editing ? "Pantry amount updated." : ingredient.name + " added to your pantry.");
  });

  onSubmit($("#recipe-form"), async form => {
    const name = cleanName(form.elements.title.value);
    if (!name) {
      form.elements.title.focus();
      throw new Error("Enter a recipe name.");
    }
    const base = Number(form.elements.base.value);
    if (!Number.isInteger(base) || base < 1 || base > 999) {
      form.elements.base.focus();
      throw new Error("Enter a whole number of servings from 1 to 999.");
    }
    const ingredients = mergeIngredients([...$("#recipe-ingredients").children].map(row =>
      getIngredient(row.querySelector('[name="ingredient"]'), row.querySelector('[name="amount"]'), row.querySelector("select"))));
    await commit(current => ({
      ...current,
      recipes: [...current.recipes, { id: current.recipes.length + 1, name, base, ingredients }]
    }));
    recipeDialog.close();
    announce(name + " added to your recipes.");
  });

  onSubmit($("#meal-form"), async () => {
    const { id, servings: portions } = pendingMeal;
    const saved = await commit(current => {
      const recipe = current.recipes.find(item => item.id === id);
      if (!recipe) return null;
      const pantry = consume(current.pantry, recipe, portions);
      return pantry && { ...current, pantry };
    });
    if (!saved) throw new Error("Your pantry changed and this meal is now short on ingredients.");
    mealDialog.close();
    const cookButton = $('[data-cook="' + id + '"]');
    (cookButton.disabled ? $("#add-recipe") : cookButton).focus();
    announce("Meal confirmed. Pantry updated.");
  });

  window.addEventListener("storage", event => {
    if (persistent && (event.key === storageKey || event.key === null)) {
      state = seed();
      state = latestState();
      render();
    }
  });
  state = latestState();
  setServings(2);
})();

(() => {
  "use strict";

  function seed() {
    return {
      pantry: [
        { name: "Rice", unit: "g", amount: "500" },
        { name: "Lentils", unit: "g", amount: "300" },
        { name: "Carrots", unit: "item", amount: "4" },
        { name: "Eggs", unit: "item", amount: "6" },
        { name: "Onions", unit: "item", amount: "2" }
      ],
      recipes: [
        {
          id: 1,
          name: "Carrot lentils",
          base: 2,
          image: "assets/carrot-lentils.webp",
          ingredients: [
            { name: "Lentils", unit: "g", amount: "150" },
            { name: "Carrots", unit: "item", amount: "2" },
            { name: "Onions", unit: "item", amount: "1" }
          ]
        },
        {
          id: 2,
          name: "Egg rice",
          base: 2,
          image: "assets/egg-rice.webp",
          ingredients: [
            { name: "Rice", unit: "g", amount: "160" },
            { name: "Eggs", unit: "item", amount: "2" },
            { name: "Carrots", unit: "item", amount: "1" }
          ]
        }
      ]
    };
  }

  // Store amounts as strings and calculate with reduced fractions to keep gram shortages exact.
  function fraction(numerator, denominator = 1n) {
    let a = numerator < 0n ? -numerator : numerator;
    let b = denominator;
    while (b !== 0n) {
      [a, b] = [b, a % b];
    }
    return [numerator / a, denominator / a];
  }

  function read(value) {
    const [numerator, denominator = "1"] = value.split("/");
    return [BigInt(numerator), BigInt(denominator)];
  }

  function write([numerator, denominator]) {
    return denominator === 1n ? String(numerator) : numerator + "/" + denominator;
  }

  function combine([a, b], [c, d], sign = 1n) {
    return fraction(a * d + sign * c * b, b * d);
  }

  function parseAmount(input, unit, allowZero = false) {
    const value = input.trim();
    let exact;
    if (unit === "item" && /^\d+$/.test(value)) {
      exact = fraction(BigInt(value));
    }
    if (unit === "g") {
      const parts = /^(\d*)(?:\.(\d+))?$/.exec(value);
      const ratio = /^(\d+)\s*\/\s*(\d+)$/.exec(value);
      if (parts && (parts[1] || parts[2])) {
        const decimals = parts[2] || "";
        exact = fraction(BigInt(parts[1] + decimals), 10n ** BigInt(decimals.length));
      } else if (ratio && BigInt(ratio[2]) > 0n) {
        exact = fraction(BigInt(ratio[1]), BigInt(ratio[2]));
      }
    }
    if (!exact || (!allowZero && exact[0] === 0n)) return null;
    return write(exact);
  }

  function format(amount, unit) {
    const [n, d] = read(amount);
    if (unit === "item") return n + (n === 1n ? " item" : " items");
    let decimal = String(n / d);
    let remainder = n % d;
    if (remainder) {
      decimal += ".";
      for (let place = 0; place < 6 && remainder; place += 1) {
        remainder *= 10n;
        decimal += remainder / d;
        remainder %= d;
      }
    }
    return (remainder ? write([n, d]) : decimal) + " g";
  }

  function cleanName(name) {
    return name.trim().replace(/\s+/g, " ");
  }

  function key({ name, unit }) {
    return unit + ":" + cleanName(name).toLowerCase();
  }

  function mergeIngredients(ingredients) {
    const grouped = new Map();
    for (const item of ingredients) {
      const id = key(item);
      const prior = grouped.get(id);
      if (prior) {
        prior.amount = write(combine(read(prior.amount), read(item.amount)));
      } else {
        grouped.set(id, { ...item });
      }
    }
    return [...grouped.values()];
  }

  function assess(recipe, pantry, servings) {
    const stocks = new Map(pantry.map(item => [key(item), item.amount]));
    return mergeIngredients(recipe.ingredients).map(item => {
      const [n, d] = read(item.amount);
      const scaledN = n * BigInt(servings);
      const scaledD = d * BigInt(recipe.base);
      const needed = item.unit === "item"
        ? fraction((scaledN + scaledD - 1n) / scaledD)
        : fraction(scaledN, scaledD);
      const left = combine(read(stocks.get(key(item)) || "0"), needed, -1n);
      return {
        ...item,
        amount: write(needed),
        shortage: left[0] < 0n ? write([-left[0], left[1]]) : null,
        remaining: write(left)
      };
    });
  }

  function consume(pantry, recipe, servings) {
    const requirements = assess(recipe, pantry, servings);
    if (requirements.some(item => item.shortage)) return null;
    const balances = new Map(requirements.map(item => [key(item), item.remaining]));
    return pantry.map(item => ({
      ...item,
      amount: balances.get(key(item)) ?? item.amount
    }));
  }

  function stock(pantry, ingredient, replace) {
    const index = pantry.findIndex(item => key(item) === key(ingredient));
    if (index < 0) return [...pantry, ingredient];
    return pantry.map((item, position) => position === index ? {
      ...item,
      amount: replace ? ingredient.amount : write(combine(read(item.amount), read(ingredient.amount)))
    } : item);
  }

  const model = { seed, parseAmount, format, cleanName, key, mergeIngredients, assess, consume, stock };
  if (typeof module === "object" && module.exports) module.exports = model;
  else window.Pantry = model;
})();

:root {
  --paper: #f8f6ef;
  --card: #fffef9;
  --ink: #273229;
  --muted: #576256;
  --line: #e2dfd3;
  --green: #284b3b;
  --green-hover: #1b352a;
  --sage: #e8eee1;
  --red: #913c28;
  --serif: Georgia, "Times New Roman", serif;
  --sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 15px/1.5 var(--sans);
}
h1, h2, h3, p, ul { margin: 0; }
ul { list-style: none; padding: 0; }
button, input, select { font: inherit; }
button { cursor: pointer; }
button:disabled { cursor: default; }
button, input, select, a { -webkit-tap-highlight-color: transparent; }
:focus-visible { outline: 3px solid #9c542c; outline-offset: 3px; }
svg { display: block; width: 20px; height: 20px; flex: 0 0 auto; }
[hidden] { display: none !important; }
.shell { width: min(calc(100% - 96px), 1200px); margin-inline: auto; }

.skip-link {
  position: fixed;
  top: 12px;
  left: 12px;
  padding: 10px 14px;
  z-index: 5;
  background: var(--card);
  color: var(--green);
  transform: translateY(-160%);
}
.skip-link:focus { transform: none; }
.masthead { border-bottom: 1px solid var(--line); background: var(--card); }
.masthead-inner { min-height: 72px; display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.brand { display: flex; align-items: center; gap: 11px; font: bold 25px/1 var(--serif); letter-spacing: -.5px; }
.brand-icon { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 12px; color: #fff; background: var(--green); }
.brand-icon svg { width: 22px; height: 22px; }
.offline { display: inline-flex; align-items: center; gap: 8px; color: var(--muted); font-size: 13px; font-weight: 600; }
.offline span { width: 8px; height: 8px; border-radius: 50%; background: #54704f; box-shadow: 0 0 0 3px var(--sage); }

.intro {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 28px;
  padding: 41px 42px 43px;
  margin: 35px 0 29px;
  border: 1px solid #dedfce;
  border-radius: 22px;
  background: #f0f0e3;
  background-image: linear-gradient(110deg, #f5f2e5, #e9edde);
}
.intro h1 { font: 400 clamp(46px, 5.6vw, 77px)/.99 var(--serif); letter-spacing: -.065em; }
.intro em { color: var(--green); font-weight: 400; }
.intro p { margin-top: 15px; font-size: 16px; color: var(--muted); }
.serving-control {
  flex: none;
  display: grid;
  justify-items: center;
  gap: 8px;
  padding: 13px 14px;
  border: 1px solid #d8dccd;
  border-radius: 14px;
  background: var(--card);
}
.serving-control label { font-size: 12px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; }
.stepper { display: flex; align-items: center; gap: 2px; }
.stepper button {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: #f6f6ed;
  color: var(--green);
}
.stepper button:disabled { opacity: .45; }
.stepper input {
  width: 52px;
  min-height: 44px;
  padding: 0 2px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--ink);
  text-align: center;
  font-size: 20px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.dashboard { display: grid; grid-template-columns: minmax(255px, .36fr) minmax(0, 1fr); align-items: start; gap: 26px; }
.panel { background: var(--card); border: 1px solid var(--line); border-radius: 17px; box-shadow: 0 3px 9px #32372807; }
.pantry { padding: 20px; }
.pantry-heading { display: flex; align-items: center; gap: 12px; padding-bottom: 17px; border-bottom: 1px solid var(--line); }
.section-icon, .ingredient-icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 11px;
  color: var(--green);
  background: var(--sage);
}
.section-icon svg { width: 23px; height: 23px; }
h2, h3 { font-family: var(--serif); font-weight: 400; letter-spacing: -.035em; line-height: 1.1; }
.pantry h2 { font-size: 26px; }
.pantry-heading p, .recipes-heading p { margin-top: 4px; color: var(--muted); font-size: 13px; }
.pantry-list { margin-block: 4px 15px; }
.pantry-list li + li { border-top: 1px solid var(--line); }
.pantry-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  width: 100%;
  min-height: 56px;
  align-items: center;
  gap: 9px;
  padding: 6px 2px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: var(--ink);
  text-align: left;
}
.ingredient-icon { width: 34px; height: 34px; border-radius: 9px; }
.ingredient-icon svg { width: 19px; height: 19px; }
.ingredient-icon.rice { background: #f2eddb; color: #635234; }
.ingredient-icon.lentils { background: #edecdc; color: #605633; }
.ingredient-icon.carrots { background: #f7e7dc; color: #893e24; }
.ingredient-icon.eggs { background: #f8efd7; color: #735019; }
.ingredient-icon.onions { background: #f0e7ec; color: #6b4b61; }
.ingredient-name { overflow-wrap: anywhere; }
.pantry-row .ingredient-name { font-weight: 650; }
.quantity { text-align: right; color: var(--muted); max-width: 11ch; overflow-wrap: anywhere; }
.edit-mark { color: #696f60; }
.edit-mark svg { width: 15px; height: 15px; }
.pantry-add { width: 100%; }

.button, .icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 9px 14px;
  border: 1px solid transparent;
  border-radius: 9px;
  font-size: 14px;
  font-weight: 700;
  line-height: 1.25;
  transition: background-color 150ms, border-color 150ms;
}
.button svg, .icon-button svg { width: 17px; height: 17px; }
.button.outline { color: var(--green); border-color: #cbd3c5; background: var(--card); }
.button.primary { color: #fff; background: var(--green); }
.button.unavailable { color: #725840; background: #f3eee5; border-color: #ebe1d3; }
.button.primary:disabled { opacity: .65; }
@media (hover: hover) {
  .button.primary:hover:enabled { background: var(--green-hover); }
  .button.outline:hover, .stepper button:hover:enabled, .pantry-row:hover, .icon-button:hover:enabled { background: var(--sage); }
}

.recipes-heading { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin: 0 0 16px; }
.recipes h2 { font-size: 35px; }
.recipe-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 17px; }
.recipe-card { overflow: hidden; display: flex; flex-direction: column; min-width: 0; }
.recipe-cover { position: relative; aspect-ratio: 2.05; background: #e8eadb; }
.recipe-cover img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 52%; display: block; }
.cover-placeholder { height: 100%; display: grid; place-items: center; color: #5a735e; background: repeating-linear-gradient(135deg, #ecf0e5 0 12px, #e8eddf 12px 24px); }
.cover-placeholder svg { width: 45px; height: 45px; }
.badge {
  position: absolute;
  top: 12px;
  left: 12px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 9px;
  border-radius: 100px;
  background: #f4f8ed;
  color: #31543b;
  font-size: 12px;
  font-weight: 750;
}
.badge svg { width: 15px; height: 15px; }
.badge.missing { color: var(--red); background: #fff2e8; }
.recipe-body { padding: 17px 17px 16px; display: flex; flex-direction: column; flex: 1; }
.recipe-body h3 { margin-bottom: 10px; font-size: clamp(25px, 2.5vw, 34px); overflow-wrap: anywhere; }
.requirements { margin-bottom: 15px; }
.requirements li, .meal-ingredients li {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, auto);
  align-items: start;
  gap: 12px;
  padding-block: 6px;
  border-bottom: 1px solid var(--line);
  font-size: 14px;
}
.requirements li > :last-child, .meal-ingredients li > :last-child {
  color: var(--muted);
  text-align: right;
  max-width: 18ch;
  overflow-wrap: anywhere;
  font-variant-numeric: tabular-nums;
}
.requirements li small { display: block; color: var(--red); font-size: 12px; font-weight: 750; }
.cook { justify-content: space-between; width: 100%; margin-top: auto; }
.cook.unavailable { justify-content: center; }

.footer { display: flex; align-items: center; gap: 8px; padding: 21px 0 26px; margin-top: 24px; border-top: 1px solid var(--line); color: var(--muted); font-size: 13px; }
.footer svg { width: 16px; height: 16px; }
.notice, .no-js { margin-bottom: 18px; padding: 12px 16px; border: 1px solid #e5cfaa; border-radius: 9px; color: #735019; background: #fff5de; }
.toast {
  position: fixed;
  z-index: 2;
  right: 24px;
  bottom: 24px;
  max-width: min(400px, calc(100% - 48px));
  padding: 12px 17px;
  border-radius: 10px;
  background: var(--green);
  color: white;
  box-shadow: 0 5px 18px #22332937;
  opacity: 0;
  pointer-events: none;
  transition: opacity 150ms;
}
.toast.visible { opacity: 1; }

dialog {
  width: min(100% - 32px, 470px);
  max-height: calc(100% - 32px);
  margin: auto;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: 16px;
  color: var(--ink);
  background: var(--card);
  box-shadow: 0 15px 65px #172b1b40;
}
dialog::backdrop { background: #1d2b24a3; }
#recipe-dialog { width: min(100% - 32px, 620px); }
.dialog-heading { display: flex; justify-content: space-between; align-items: start; gap: 10px; margin-bottom: 12px; }
.dialog-heading h2 { padding-top: 5px; font-size: 32px; overflow-wrap: anywhere; }
.icon-button { flex: 0 0 auto; width: 44px; min-height: 44px; padding: 0; background: #f3f4eb; color: var(--green); }
.icon-button:disabled { opacity: .4; }
.dialog-hint { margin-bottom: 17px; color: var(--muted); }
.field { display: grid; min-width: 0; align-content: start; gap: 5px; color: var(--ink); font-size: 13px; font-weight: 650; }
.field input, .field select {
  width: 100%;
  min-height: 44px;
  padding: 8px 9px;
  border: 1px solid #cbcfc2;
  border-radius: 7px;
  color: var(--ink);
  background: white;
  font-size: 16px;
  font-weight: 400;
}
.field :is(input[readonly], select:disabled) { background: #f0f1ea; color: var(--muted); opacity: 1; }
.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 12px; }
.form-grid.recipe-fields { grid-template-columns: 1fr 105px; }
fieldset { padding: 0; margin: 19px 0 10px; border: 0; min-width: 0; }
legend { margin-bottom: 7px; padding: 0; font-weight: 700; }
.ingredient-form-row {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(66px, 1fr) minmax(76px, 1fr) 44px;
  gap: 8px;
  align-items: end;
  margin-bottom: 8px;
}
.dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 19px; }
.form-error { margin-top: 12px; color: var(--red); font-weight: 650; }
.meal-ingredients li { padding-block: 9px; }
.meal-ingredients li span { overflow-wrap: anywhere; }

@media (max-width: 1050px) {
  .shell { width: calc(100% - 56px); }
  .dashboard { gap: 18px; }
}
@media (max-width: 820px) {
  .shell { width: calc(100% - 36px); }
  .intro { padding: 32px; margin-top: 24px; }
  .dashboard { grid-template-columns: 1fr; gap: 24px; }
  .pantry-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 16px; }
  .pantry-list li { border-bottom: 1px solid var(--line); }
  .pantry-list li + li { border-top: 0; }
}
@media (max-width: 510px) {
  .masthead-inner { min-height: 60px; }
  .brand { font-size: 22px; gap: 8px; }
  .brand-icon { width: 34px; height: 34px; }
  .offline { font-size: 11px; }
  .intro { display: grid; padding: 22px 18px 18px; gap: 20px; margin-bottom: 18px; }
  .intro h1 { font-size: clamp(39px, 9.4vw, 48px); }
  .intro p { margin-top: 10px; font-size: 14px; }
  .serving-control { display: flex; justify-content: space-between; padding: 5px 7px 5px 12px; }
  .pantry { padding: 15px; }
  .pantry-list { display: block; }
  .recipe-list { grid-template-columns: 1fr; }
  dialog { padding: 16px; }
}
@media (max-width: 365px) {
  .ingredient-form-row { grid-template-columns: 1fr 1fr 44px; }
  .ingredient-form-row .field:first-child { grid-column: 1 / -1; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0s !important; }
}
